import{_ as l,o as i,c as e,O as t}from"./chunks/framework.b9c6cb60.js";const p="/assets/bj1.b3cce765.png",r="/assets/bj2.9f6c946d.png",o="/assets/bj3.da8cec28.png",h="/assets/bj4.aee2082e.png",s="/assets/bj5.804a126d.png",n="/assets/bj6.be0604dc.png",k=JSON.parse('{"title":"部件列表","description":"","frontmatter":{},"headers":[],"relativePath":"技术管理/部件列表.md","filePath":"技术管理/部件列表.md"}'),u={name:"技术管理/部件列表.md"};function c(d,a,_,b,m,q){return i(),e("div",null,a[0]||(a[0]=[t('<h1 id="部件列表" tabindex="-1">部件列表 <a class="header-anchor" href="#部件列表" aria-label="Permalink to &quot;部件列表&quot;">​</a></h1><blockquote><p>部件列表位于技术管理板块，可添加部件系列，在系列中新增部件，新增的部件支持维护路线，复制，编辑，删除 等操作.</p></blockquote><h4 id="_1-新增-编辑部件系列" tabindex="-1">1.新增/编辑部件系列 <a class="header-anchor" href="#_1-新增-编辑部件系列" aria-label="Permalink to &quot;1.新增/编辑部件系列&quot;">​</a></h4><ul><li><p>默认显示所有系列，鼠标悬浮在系列上面可点击＋新增系列</p><p>-新增的系列可再加子系列，子系列也可以往下面延申</p><p>-如果该系列下有部件数据，就无法删除，没有数据的 可删除</p><p>-可双击系列名称更改名称或者调换系列位置（也可手动拖拽调整系列位置）</p><p>-分类树支持拖拽调整宽度</p></li></ul><h4 id="_2-新增部件" tabindex="-1">2.新增部件 <a class="header-anchor" href="#_2-新增部件" aria-label="Permalink to &quot;2.新增部件&quot;">​</a></h4><ul><li><p>点击新增部件按钮添加部件</p><p>-在新增部件之前需选择对应的系列（放置的位置）</p><p>-新增的部件名称/规格可以重复</p><p>-如果在创建部件时状态选择了停用，那这个部件就不可用</p></li></ul><h4 id="_3-编辑功能" tabindex="-1">3.编辑功能 <a class="header-anchor" href="#_3-编辑功能" aria-label="Permalink to &quot;3.编辑功能&quot;">​</a></h4><ul><li>可在原有新增的部件上进行编辑修改</li></ul><h4 id="_4-复制功能" tabindex="-1">4.复制功能 <a class="header-anchor" href="#_4-复制功能" aria-label="Permalink to &quot;4.复制功能&quot;">​</a></h4><ul><li>可在这个部件的基础上去复制一个相同的部件出来，能够复制全部信息</li></ul><h4 id="_5-删除功能" tabindex="-1">5.删除功能 <a class="header-anchor" href="#_5-删除功能" aria-label="Permalink to &quot;5.删除功能&quot;">​</a></h4><ul><li><p>可以通过删除按钮进行删除操作</p></li><li><p>已经进行合同签章的部件不允许进行删除</p></li></ul><h4 id="_6-批量编辑" tabindex="-1">6.批量编辑 <a class="header-anchor" href="#_6-批量编辑" aria-label="Permalink to &quot;6.批量编辑&quot;">​</a></h4><ul><li><p>先勾选需要批量编辑的部件才能触发批量编辑按钮（默认置灰，只有勾选以后才提亮）</p></li><li><p>可一键选择/取消</p></li></ul><p><img src="'+p+'" alt="如图所示"></p><h4 id="_7-批量导入部件" tabindex="-1">7.批量导入部件 <a class="header-anchor" href="#_7-批量导入部件" aria-label="Permalink to &quot;7.批量导入部件&quot;">​</a></h4><ul><li><p>点击批量导入，先下载模板（注意下载的模板只适用于批量导入部件里面上传的模板)</p></li><li><p>点开下载的模板进行编辑（编辑时请阅读表格上面的提示文案，以防导入时出现错误，从而无法导入）</p><p>-模板中的图纸号就是文件库管理列表中所保存的文件号</p><p>-模板中的检验项目名称就是技术部检验项目列表中所添加的检验项</p></li><li><p>点击或者拖拽所保存的模板（只有在部件的批量导入中下载的模板才能上传，其他无效）进行上传</p></li><li><p>上传成功会弹出显示上传的数据，可选择性导入或者一键导入（如果无法导入，请滑动到页面最后，查看提示信息，可能存在编辑时出现的错误，需重新更改再次上传）</p></li></ul><h4 id="_8-图纸" tabindex="-1">8.图纸 <a class="header-anchor" href="#_8-图纸" aria-label="Permalink to &quot;8.图纸&quot;">​</a></h4><ul><li>点击“图纸”字段下信息数据可查看当前部件上传文件，并支持下载与预览</li></ul><h4 id="_9-维护检验准则" tabindex="-1">9.维护检验准则 <a class="header-anchor" href="#_9-维护检验准则" aria-label="Permalink to &quot;9.维护检验准则&quot;">​</a></h4><ul><li><p>添加检验项目（支持添加多个检验项目）</p><p>-检验项目来源于检验项目列表</p><p>-鼠标悬浮在任意一个检验项目上面，出现删除的图标可删除</p></li></ul><h4 id="_10-技术对接人-备注" tabindex="-1">10.技术对接人/备注 <a class="header-anchor" href="#_10-技术对接人-备注" aria-label="Permalink to &quot;10.技术对接人/备注&quot;">​</a></h4><ul><li><p>悬浮在对接人下方名称可查看这个人员的基本信息</p></li><li><p>点击备注信息可打开弹窗查看完整的备注信息</p></li></ul><h4 id="_11-表头设置" tabindex="-1">11.表头设置 <a class="header-anchor" href="#_11-表头设置" aria-label="Permalink to &quot;11.表头设置&quot;">​</a></h4><ul><li>点击表头设置图标可更改表头字段的显示/隐藏</li></ul><p><img src="'+r+'" alt="如图所示"></p><h4 id="_12-维护路线" tabindex="-1">12.维护路线 <a class="header-anchor" href="#_12-维护路线" aria-label="Permalink to &quot;12.维护路线&quot;">​</a></h4><ul><li><p>点击可添加工艺路线，支持设置默认路线，可在路线中直接更换别的部件去维护路线</p></li><li><p>启用/停用：停用时无法使用该路线，启用时可以使用该路线</p></li><li><p>已添加的工艺路线可点击路线标签中的删除图标进行删除</p></li><li><p>点击工艺路线中的工序标签可查看当前工序绑定物料</p></li></ul><h4 id="_13-配套物料" tabindex="-1">13.配套物料 <a class="header-anchor" href="#_13-配套物料" aria-label="Permalink to &quot;13.配套物料&quot;">​</a></h4><p>1.导入配套物料</p><ul><li><p>点击图标，先下载模板（注意下载的模板只适用于部件配套物料里面上传的模板)</p></li><li><p>点开下载的模板进行编辑（编辑时请阅读表格上面的提示文案，以防导入时出现错误，从而无法导入）</p></li><li><p>点击或者拖拽所保存的模板（只有在部件配套物料导入中下载的模板才能上传，其他无效）进行上传</p></li><li><p>上传成功会弹出显示上传的数据，可选择性导入或者一键导入（如果无法导入，请滑动到页面最后，查看提示信息，可能存在编辑时出现的错误，需从新更改再次上传）</p></li></ul><p>2.手动添加配套物料</p><ul><li><p>点击添加配套物料按钮可新增配套物料，或使用快捷键（键盘向下按键添加配套物料，键盘向上按键删除配套物料）</p></li><li><p>添加的配套物料支持删除</p></li><li><p>选择物料的分类（产品，部件，零件，原料，其他)，物料名称(物料下拉列表会去除已停用的物料)，规格，配套数量，单位，工序号</p></li></ul><p><img src="'+o+'" alt="如图所示"></p><h4 id="_15-工艺路线" tabindex="-1">15.工艺路线 <a class="header-anchor" href="#_15-工艺路线" aria-label="Permalink to &quot;15.工艺路线&quot;">​</a></h4><ul><li>可查看这个产品所使用的工艺路线详情</li></ul><h4 id="_16-bom表" tabindex="-1">16.BOM表 <a class="header-anchor" href="#_16-bom表" aria-label="Permalink to &quot;16.BOM表&quot;">​</a></h4><ul><li>点击查看这个产品下所用到的物料明细</li></ul><p><img src="'+h+'" alt="如图所示"></p><h4 id="_17-批量更新部件" tabindex="-1">17.批量更新部件 <a class="header-anchor" href="#_17-批量更新部件" aria-label="Permalink to &quot;17.批量更新部件&quot;">​</a></h4><ul><li><p>点击更新部件图标按键，先下载模板（注意下载的模板只适用于批量更新部件里面上传的模板)</p></li><li><p>点开下载的模板进行编辑（编辑时请阅读表格上面的提示文案，以防导入时出现错误，从而无法导入）</p><p>-模板中的图纸号就是文件库管理列表中所保存的文件号</p></li><li><p>点击或者拖拽所保存的模板（只有在部件的批量更新中下载的模板才能上传，其他无效）进行上传</p></li><li><p>上传成功会弹出显示上传的数据，可选择性导入或者一键导入（如果无法导入，请滑动到页面最后，查看提示信息，可能存在编辑时出现的错误，需重新更改再次上传）</p></li></ul><p><img src="'+s+'" alt="如图所示"></p><h4 id="_18-导出" tabindex="-1">18.导出 <a class="header-anchor" href="#_18-导出" aria-label="Permalink to &quot;18.导出&quot;">​</a></h4><ul><li>点击导出按键，出现导出弹窗，可在输入框中输入需导出数据数量，点击导出后，页面出现“数据导出中”提示弹窗，当导出任务结束时，可在本地查看导出文件</li></ul><p><img src="'+n+'" alt="如图所示"></p>',45)]))}const x=l(u,[["render",c]]);export{k as __pageData,x as default};
